code.formula:
REM {内容：文書を閉じる（アイコンはフォーム用）
		2006/04/07 DLS.Chida 新規作成};

@Command([FileCloseWindow])

REM {内容：印刷
		2006/04/07 DLS.Chida 新規作成};

@Command([FilePrint])

REM {内容：文書を編集する（WF用_フォーム特化の保存アクション）
		2006/06/07 DLS.Chida 新規作成};

@Command([EditDocument])

REM {内容：文書を保存する（WF用_フォーム特化の保存アクション）
		2006/06/07 DLS.Chida 新規作成};

@Command([FileSave])

REM {StatusCodeが""は新規作成時を対象としている};

tmp := StatusCode;
@If(
  ( (tmp = "" | tmp = "1000" | tmp = "2000" | tmp = "6000") & @Contains( @UserRoles ; "[DanTanto]") != @False) |
    (tmp = "5000" & @Contains( @UserRoles ; "[ImuSyai]") != @False ) ; @False; @True )

REM {「役付回付」アクションの表示条件
      2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};
REM {StatusCodeが""は新規作成時を対象としている};

@If( (StatusCode = "" | StatusCode = "1000") & (@Contains( @UserRoles ; "[DanTanto]")); @False ; @True )

REM {「役付承認」アクションの表示条件
      2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

@If( (StatusCode = "2000") & (@Contains( @UserRoles ; "[DanTanto]")); @False ; @True )

REM {「依頼送付」アクションの表示条件
      2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

@If( (StatusCode = "2500") & (@Contains( @UserRoles ; "[DanTanto]")); @False ; @True )

REM {「受付」アクションの表示条件
      2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

@If( (StatusCode = "3000") & (@Contains( @UserRoles ; "[ImuUke]")); @False ; @True )

REM {「依頼確認」アクションの表示条件
      2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

@If( (StatusCode = "4000") & (@Contains( @UserRoles ; "[ImuSyai]")); @False ; @True )

REM {「回答送信」アクションの表示条件
      2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

@If( (StatusCode = "5000") & (@Contains( @UserRoles ; "[ImuSyai]")); @False ; @True )

REM {「再依頼」アクションの表示条件
      2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

@If( (StatusCode = "6000") & (@Contains( @UserRoles ; "[DanTanto]")); @False ; @True )

REM {「回答確認」アクションの表示条件
      2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

@If( (StatusCode = "6000") & (@Contains( @UserRoles ; "[DanTanto]")); @False ; @True )

@ThisValue;

REM {@If(StatusCode = "1000";"起案中";
	StatusCode = "2000";"役付承認待ち";
	StatusCode = "3000";"依頼送信済";
	StatusCode = "4000";"受付済";
	StatusCode = "5000";"回答作成中";
	StatusCode = "6000";"回答送信済";
	StatusCode = "7000";"回答確認済";"")};

REM {「01団事（編集・参照）」サブフォームの表示条件
						2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

REM {「tmpA」･･･進捗コードフラグ（"1"がたてばOK）
	　「tmpB」･･･アクセスユーザー保持ロールフラグ（"1"がたてば保持している）};
tmpA := "";
tmpB := "";


REM {進捗コードの判定（""か"1000"か"2000"ならOK）→""の場合、新規作成時を対象とする};
@If(( StatusCode = "") | ( StatusCode = "1000") | ( StatusCode = "2000") ;tmpA := "1" ; tmpA := "0");


REM {アクセスユーザー保持ロールの判定};
@If( @Contains( @UserRoles ; "[DanTanto]") ;tmpB := "1" ; tmpB := "0");


REM {両方1がたった時のみ「01団事（編集）」サブフォームを表示};
@If ( (( tmpA = "1" ) & ( tmpB = "1" )) ; "sfmDanjiEdit" ; "sfmDanjiDisp" )

REM {「02契医（編集）」サブフォームの表示条件
						2006/05/31　DLS.Chida新規作成};
REM {2006/06/16 FSI sasaki：表示条件不備の対応};

REM {「tmpA」･･･進捗コードフラグ（"1"がたてばOK）
	　「tmpB」･･･アクセスユーザー保持ロールフラグ（"1"がたてば保持している）};

tmpA := "";
tmpB := "";

REM {進捗コードの判定（"5000"ならOK）};
@If((StatusCode = "5000") ;tmpA := "1" ; tmpA := "0");

REM {アクセスユーザー保持ロールの判定};
@If( @Contains( @UserRoles ; "[ImuSyai]") ;tmpB := "1" ; tmpB := "0");

REM {両方1がたった時のみ「02契医（編集）」サブフォームを表示};
@If ( (( tmpA = "1" ) & ( tmpB = "1" )) ; "sfmKeiiEdit"; "sfmKeiiDisp" )

REM {内容：文書を閉じる（アイコンは休日設定フォーム用）
		2006/04/07 DLS.Chida 新規作成};

@Command([FileCloseWindow])

REM {内容：文書を編集する（通常用）
		2006/04/07 DLS.Chida 新規作成};

@Command([EditDocument])

REM {内容：文書を保存する（通常用）
		2006/04/07 DLS.Chida 新規作成};

@Command([FileSave])

