		2006/04/07 DLS.Chida 新規作成};

@Command([FileCloseWindow])

REM {内容：新規連絡票の作成を行う
		2006/05/08 FSI.IDUKI 新規作成};

@Command([Compose];"frmSelectionMente")

REM {
【内容】	：	選択肢のソートのための判定式。選択肢の追加時にデータ変更が必要ない。　 
【作成日】 	：	2006/05/30
【作成者】 	：	DLS.Chida
};


@If(MenteTarget = "商品";"01";
	MenteTarget = "請求事由";"02";
	MenteTarget = "依頼内容";"03";
	MenteTarget = "回答内容";"04";"99")
